import sys
import re

def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    # Increase recursion depth for deep dependency chains up to 2574 cells
    sys.setrecursionlimit(max(sys.getrecursionlimit(), 10000))

    CELL_REGEX = re.compile(r'^[A-Z](?:[1-9][0-9]?)$')

    def parse_cell_coord(name: str):
        col = ord(name[0]) - ord('A')
        row = int(name[1:])
        return col, row

    def cell_name_from_coord(col: int, row: int) -> str:
        return f"{chr(ord('A') + col)}{row}"

    # Tokenizer
    TOKEN_REGEX = re.compile(
        r'\s*(?:'
        r'(<=|>=|<>|<|>|=)'
        r'|([A-Z][1-9][0-9]?:[A-Z][1-9][0-9]?)'
        r'|([A-Z][1-9][0-9]?)'
        r'|(\d+)'
        r'|([A-Za-z]+)'
        r'|([+*/(),-])'
        r')'
    )

    class Parser:
        def __init__(self, text: str):
            self.tokens = []
            pos = 0
            n = len(text)
            while pos < n:
                m = TOKEN_REGEX.match(text, pos)
                if not m:
                    break
                pos = m.end()
                val = m.group(0).strip()
                if val:
                    self.tokens.append(val)
            self.idx = 0

        def peek(self):
            if self.idx < len(self.tokens):
                return self.tokens[self.idx]
            return None

        def next(self):
            tok = self.peek()
            self.idx += 1
            return tok

        def expect(self, expected):
            tok = self.next()
            if tok != expected:
                raise ValueError(f"Expected {expected}, got {tok}")
            return tok

        def parse_formula(self):
            return self.parse_add_sub()

        def parse_add_sub(self):
            node = self.parse_mul_div()
            while self.peek() in ('+', '-'):
                op = self.next()
                right = self.parse_mul_div()
                node = ('binop', op, node, right)
            return node

        def parse_mul_div(self):
            node = self.parse_unary()
            while self.peek() in ('*', '/'):
                op = self.next()
                right = self.parse_unary()
                node = ('binop', op, node, right)
            return node

        def parse_unary(self):
            if self.peek() == '-':
                self.next()
                operand = self.parse_unary()
                return ('unary', '-', operand)
            return self.parse_atom()

        def parse_atom(self):
            tok = self.peek()
            if tok == '(':
                self.next()
                node = self.parse_formula()
                self.expect(')')
                return node
            elif tok is not None and tok.isdigit():
                self.next()
                return ('literal', int(tok))
            elif tok is not None and tok.upper() in ('SUM', 'MIN', 'MAX', 'IF'):
                func_name = self.next().upper()
                self.expect('(')
                if func_name == 'IF':
                    left = self.parse_formula()
                    op = self.next()
                    right = self.parse_formula()
                    self.expect(',')
                    then_branch = self.parse_formula()
                    self.expect(',')
                    else_branch = self.parse_formula()
                    self.expect(')')
                    return ('if', (left, op, right), then_branch, else_branch)
                else:
                    args = []
                    while True:
                        t = self.peek()
                        if t is not None and ':' in t:
                            self.next()
                            start_str, end_str = t.split(':')
                            args.append(('range', start_str, end_str))
                        else:
                            arg = self.parse_formula()
                            args.append(('formula', arg))
                        if self.peek() == ',':
                            self.next()
                        else:
                            break
                    self.expect(')')
                    return ('func', func_name, args)
            elif tok is not None and CELL_REGEX.match(tok):
                self.next()
                return ('cell', tok)
            else:
                raise ValueError(f"Unexpected token: {tok}")

    parsed_formulas = {}
    for name, content in cells.items():
        s = content.strip()
        if not s.startswith('='):
            try:
                val = int(s)
                parsed_formulas[name] = ('literal', val)
            except ValueError:
                p = Parser(s)
                parsed_formulas[name] = p.parse_formula()
        else:
            p = Parser(s[1:])
            parsed_formulas[name] = p.parse_formula()

    values = {}
    in_progress = set()

    def eval_node(node):
        kind = node[0]
        if kind == 'literal':
            return node[1]

        elif kind == 'cell':
            name = node[1]
            return get_cell_value(name)

        elif kind == 'unary':
            val = eval_node(node[2])
            if isinstance(val, str):
                return val
            return -val

        elif kind == 'binop':
            op, left_node, right_node = node[1], node[2], node[3]
            left_val = eval_node(left_node)
            if isinstance(left_val, str):
                return left_val
            right_val = eval_node(right_node)
            if isinstance(right_val, str):
                return right_val

            if op == '+':
                return left_val + right_val
            elif op == '-':
                return left_val - right_val
            elif op == '*':
                return left_val * right_val
            elif op == '/':
                if right_val == 0:
                    return "#DIV/0!"
                # Truncate toward zero
                sign = -1 if (left_val < 0) ^ (right_val < 0) else 1
                return sign * (abs(left_val) // abs(right_val))

        elif kind == 'if':
            cond, then_branch, else_branch = node[1], node[2], node[3]
            c_left, op, c_right = cond
            lv = eval_node(c_left)
            if isinstance(lv, str):
                return lv
            rv = eval_node(c_right)
            if isinstance(rv, str):
                return rv

            res = False
            if op == '=':
                res = (lv == rv)
            elif op == '<>':
                res = (lv != rv)
            elif op == '<':
                res = (lv < rv)
            elif op == '<=':
                res = (lv <= rv)
            elif op == '>':
                res = (lv > rv)
            elif op == '>=':
                res = (lv >= rv)

            if res:
                return eval_node(then_branch)
            else:
                return eval_node(else_branch)

        elif kind == 'func':
            func_name, args = node[1], node[2]
            vals = []
            for arg_kind, *arg_data in args:
                if arg_kind == 'formula':
                    v = eval_node(arg_data[0])
                    if isinstance(v, str):
                        return v
                    vals.append(v)
                elif arg_kind == 'range':
                    start_str, end_str = arg_data[0], arg_data[1]
                    c1, r1 = parse_cell_coord(start_str)
                    c2, r2 = parse_cell_coord(end_str)
                    min_c, max_c = min(c1, c2), max(c1, c2)
                    min_r, max_r = min(r1, r2), max(r1, r2)
                    for r in range(min_r, max_r + 1):
                        for c in range(min_c, max_c + 1):
                            cn = cell_name_from_coord(c, r)
                            if cn in cells:
                                v = get_cell_value(cn)
                                if isinstance(v, str):
                                    return v
                                vals.append(v)

            if func_name == 'SUM':
                return sum(vals) if vals else 0
            elif func_name == 'MIN':
                return min(vals) if vals else 0
            elif func_name == 'MAX':
                return max(vals) if vals else 0

        raise ValueError(f"Unknown node: {node}")

    def get_cell_value(name: str):
        if name not in cells:
            return 0
        if name in in_progress:
            return "#CYCLE!"
        if name in values:
            return values[name]

        in_progress.add(name)
        val = eval_node(parsed_formulas[name])
        in_progress.remove(name)
        values[name] = val
        return val

    result = {}
    for name in cells:
        result[name] = get_cell_value(name)

    return result
